 $name='db_sondir_'.date('Ymd_His').'.sql';$path=$dir.'/'.$name;$mysqldump='C:\\laragon\\bin\\mysql\\mysql-8.4.3-winx64\\bin\\mysqldump.exe';$cmd='"'.$mysqldump.'" --user=root --host=127.0.0.1 --single-transaction --routines db_sondir > "'.$path.'"';exec($cmd,$out,$code);if($code===0&&is_file($path)){audit($pdo,'Membuat backup database');flash('success','Backup database berhasil dibuat.');}else{flash('danger','Backup gagal dibuat.');}redirect('pengaturan/backup.php');}
